<?php
namespace EyeDonation\SiteMigrations;
defined('ABSPATH') || exit;
final class DonorPanelMigration {
 const ID='013_update_donor_panel';
 public static function checksum(){return hash('sha256',file_get_contents(__FILE__).file_get_contents(get_theme_file_path('/inc/donor-panel.php')));}
 public static function plan(){preflight();$id=(int)get_option('page_on_front');$p=get_post($id);if(get_option('show_on_front')!=='page'||!$p||$p->post_type!=='page'||!current_user_can('edit_post',$id))fail('Select an editable static homepage first.');$after=ed_update_donor_panel($p->post_content,true);return ['key'=>'homepage.donor.panel','kind'=>'page','id'=>$id,'before'=>$p->post_content,'after'=>$after,'action'=>$p->post_content===$after?'already-satisfied':'update'];}
 public static function preview(){ $state=history()[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('013 checksum changed.');$p=['actor'=>get_current_user_id(),'checksum'=>self::checksum(),'operation'=>self::plan(),'created'=>time()];update_option('edm_donor_panel_preview',$p,false);return $p; }
 public static function run(){preflight();$token=lock_acquire();try{$h=history();$state=$h[self::ID]??[];if(isset($state['checksum'])&&$state['checksum']!==self::checksum())fail('013 checksum changed.');if(($state['status']??'')==='completed')return 'Donor panel migration already completed; editorial changes preserved.';$p=get_option('edm_donor_panel_preview');if(!$p||$p['actor']!==get_current_user_id()||$p['checksum']!==self::checksum()||$p['created']<time()-DAY_IN_SECONDS)fail('Fresh donor panel preview required.');$op=self::plan();$expected=$state['operation']??$p['operation'];if($op['id']!==$expected['id']||$op['after']!==$expected['after']||($op['before']!==$expected['before']&&$op['action']!=='already-satisfied'))fail('Homepage changed after preview.');$h[self::ID]=array_merge($state,['status'=>'running','checksum'=>self::checksum(),'actor'=>get_current_user_id(),'run_id'=>$state['run_id']??wp_generate_uuid4(),'started'=>$state['started']??time(),'operation'=>$expected,'destination_id'=>$op['id']]);lock_check($token);save_history($h);apply_operation($op);lock_check($token);if(get_post_field('post_content',$op['id'])!==$expected['after'])fail('Donor panel update verification failed.');$h[self::ID]['status']='completed';$h[self::ID]['completed']=time();save_history($h);return 'Sticky donor signup panel installed; other homepage sections preserved.';}finally{lock_release($token);}}
}
foreach(['preview','run'] as $mode)add_action('admin_post_edm_donor_panel_'.$mode,function()use($mode){if(!current_user_can('manage_options'))wp_die('Unauthorized');check_admin_referer('edm_donor_panel_'.$mode);try{if($mode==='run'&&empty($_POST['backup']))fail('Backup acknowledgment required.');$result=$mode==='preview'?DonorPanelMigration::preview():DonorPanelMigration::run();update_option('edm_donor_panel_notice',is_string($result)?$result:'Preview ready.',false);}catch(\Throwable $e){update_option('edm_donor_panel_notice',$e->getMessage(),false);}wp_safe_redirect(admin_url('tools.php?page=eyedonation-migrations#edm-donor-panel-update'));exit;});
add_action('admin_footer',function(){if(($_GET['page']??'')!=='eyedonation-migrations'||!current_user_can('manage_options'))return;echo '<div class="wrap" id="edm-donor-panel-update"><h2>013 — Sticky donor signup panel</h2><p>Updates only the donor signup panel. The theme keeps it fixed at the right viewport edge. Status: '.esc_html(history()[DonorPanelMigration::ID]['status']??'pending').'</p><p role="status">'.esc_html(get_option('edm_donor_panel_notice','')).'</p>';foreach(['preview'=>'Preview donor panel','run'=>'Apply / Resume donor panel'] as $mode=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_donor_panel_'.$mode.'">';wp_nonce_field('edm_donor_panel_'.$mode);if($mode==='run')echo '<p><label><input type="checkbox" name="backup" value="1" required> I have a recoverable backup.</label></p>';submit_button($label);echo '</form>';}$p=get_option('edm_donor_panel_preview');if($p)echo '<details><summary>Current / proposed content</summary><pre>'.esc_html(wp_json_encode($p['operation'],JSON_PRETTY_PRINT)).'</pre></details>';echo '</div>';});
